INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('4930a2a67d7c972f0068','Amedex 2023.pdf','812','Mixed/Unclassified','You are a resident medical officer in a high-risk pregnancy clinic. One of your patients with past obstetrical history of placenta previa and cesarean section is found to have breech presentation at 36 weeks gestation. Which one of the following is a
risk factor for increased chance of term breech presentation?','{"A":"Nulliparity.","B":"Prior cesarean section.","C":"Fetal anomalies.","D":"Polyhydramnios.","E":"All of the above."}','E','Contributing factors to breech presentation include the following:
Maternal factors:
Nulliparity
Previous breech birth
Uterine (anatomical) anomaly
Placental abnormalities (previa, cornual)
Oligohydramnios
Polyhydramnios
Multiple pregnancy
Grand multiparity
Fetal factors:
Extended fetal legs
Short umbilical cord
Early gestation
Fetal abnormality
Poor fetal growth
All the options are contributing factors to breech presentation.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"440","duplicate_group_id":"exact-85d764d74346","duplicate_sources":[{"record_id":"4930a2a67d7c972f0068","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":812,"source_qid":"440"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"4930a2a67d7c972f0068","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":812,"source_qid":"440","domain_hint":"Mixed/Unclassified","stem":"You are a resident medical officer in a high-risk pregnancy clinic. One of your patients with past obstetrical history of placenta previa and cesarean section is found to have breech presentation at 36 weeks gestation. Which one of the following is a\nrisk factor for increased chance of term breech presentation?","options":{"A":"Nulliparity.","B":"Prior cesarean section.","C":"Fetal anomalies.","D":"Polyhydramnios.","E":"All of the above."},"source_answer":"E","source_explanation":"Contributing factors to breech presentation include the following:\nMaternal factors:\nNulliparity\nPrevious breech birth\nUterine (anatomical) anomaly\nPlacental abnormalities (previa, cornual)\nOligohydramnios\nPolyhydramnios\nMultiple pregnancy\nGrand multiparity\nFetal factors:\nExtended fetal legs\nShort umbilical cord\nEarly gestation\nFetal abnormality\nPoor fetal growth\nAll the options are contributing factors to breech presentation.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"mediu