INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('da38da0498f1d8d6d2d7','Amedex 2023.pdf','813','Mixed/Unclassified','The fetus of a 35-year-old woman was found to be in breech position at 32 weeks gestation. At 37 weeks gestation, ultrasonography confirms that the breech presentation has presisted . External cephalic version is attempted but fails to reposition
the fetus to cephalic. Which one of the following is the next best step in management?','{"A":"Systemic steroids.","B":"Elective cesarean delivery at 38 weeks gestation.","C":"Emergency cesarean delivery.","D":"Labor induction now.","E":"Repeat external cephalic version after 38 weeks again."}','B','In some cases, breech presentation spontaneously turns into cephalic presentation. The chance of spontaneous version from breech to cephalic diminishes with advancing gestation age; however, this may still occur in up to 25 % of breech
pregnancies after 36 weeks. With persisting breech presentation beyond 36-37 weeks, external cephalic version (ECV) is recommended to be tried from 36 weeks for nulliparous women and 37 weeks for multiparous women. If ECV fails, delivery
either through elective caesarean section or, if no contraindication, vaginal delivery is booked and performed after 38.5 weeks.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"441","duplicate_group_id":"exact-c817f00cbf46","duplicate_sources":[{"record_id":"da38da0498f1d8d6d2d7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":813,"source_qid":"441"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"da38da0498f1d8d6d2d7","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":813,"source_qid":"441","domain_hint":"Mixed/Unclassified","stem":"The fetus of a 35-year-old woman was found to be in breech position at 32 weeks gestation. At 37 weeks gestation, ultrasonography confirms that the breech presentation has presisted . External cephalic version is attempted but fails to reposition\nthe fetus to cephalic. Which one of the following is the next best step in management?","options":{"A":"Systemic steroids.","B":"Elective cesarean delivery at 38 weeks gestation.","C":"Emergency cesarean delivery.","D":"Labor induction now.","E":"Repeat external cephalic version after 38 weeks again."},"source_answer":"B","source_explanation":"In some cases, breech presentation spontaneously turns into cephalic presentation. The chance of spontaneous version from breech to cephalic diminishes with advancing gestation age; however, this may still occur in up to 25 % of breech\npregnancies after 36 weeks. With persisting breech presentation beyond 36-37 weeks, external cephalic version (ECV) is recommended to be tried from 36 weeks for nulliparous women and 37 wee