INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('da38da0498f1d8d6d2d7','src-v294-687f312c','441','813','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','The fetus of a 35-year-old woman was found to be in breech position at 32 weeks gestation. At 37 weeks gestation, ultrasonography confirms that the breech presentation has presisted . External cephalic version is attempted but fails to reposition
the fetus to cephalic. Which one of the following is the next best step in management?',NULL,'B','In some cases, breech presentation spontaneously turns into cephalic presentation. The chance of spontaneous version from breech to cephalic diminishes with advancing gestation age; however, this may still occur in up to 25 % of breech
pregnancies after 36 weeks. With persisting breech presentation beyond 36-37 weeks, external cephalic version (ECV) is recommended to be tried from 36 weeks for nulliparous women and 37 weeks for multiparous women. If ECV fails, delivery
either through elective caesarean section or, if no contraindication, vaginal delivery is booked and performed after 38.5 weeks.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"441","duplicate_group_id":"exact-c817f00cbf46","duplicate_sources":[{"record_id":"da38da0498f1d8d6d2d7","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":813,"source_qid":"441"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
