INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('0c54838a69a52dbf39cb','Amedex 2023.pdf','818','Mixed/Unclassified','A 48-year-old woman presents complaining of hot flushes, insomnia and mood swings. She has been on sertraline for mood swings and also takes over-the-counter vitamins. Which one of the following is incorrect regarding menopause?','{"A":"Decreased estrogen level.","B":"Increased serum LH level.","C":"Decreased serum FSH.","D":"Increased LDL level.","E":"Decreased bone density."}','C','Menopause is characterized by irregular menstrual cycles and marked hormonal fluctuations, often accompanied by hot flushes, sleep disturbances, mood symptoms, and vaginal dryness.
Eventual depletion of oocytes and ovarian follicles in the ovaries result in drop in estrogen level and elevation of serum FSH and LH levels. Decrease in serum estrogen results in the characteristic features of menopause. Long term effects of low
estrogen include osteoporosis and vaginal atrophy. After menopause there is a rise in LDL level.
Serum FSH is elevated (not decreased) in perimenopausal period and causes hot flushes.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"89","duplicate_group_id":"exact-841e1c5bbc8d","duplicate_sources":[{"record_id":"0c54838a69a52dbf39cb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":818,"source_qid":"89"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"0c54838a69a52dbf39cb","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":818,"source_qid":"89","domain_hint":"Mixed/Unclassified","stem":"A 48-year-old woman presents complaining of hot flushes, insomnia and mood swings. She has been on sertraline for mood swings and also takes over-the-counter vitamins. Which one of the following is incorrect regarding menopause?","options":{"A":"Decreased estrogen level.","B":"Increased serum LH level.","C":"Decreased serum FSH.","D":"Increased LDL level.","E":"Decreased bone density."},"source_answer":"C","source_explanation":"Menopause is characterized by irregular menstrual cycles and marked hormonal fluctuations, often accompanied by hot flushes, sleep disturbances, mood symptoms, and vaginal dryness.\nEventual depletion of oocytes and ovarian follicles in the ovaries result in drop in estrogen level and elevation of serum FSH and LH levels. Decrease in serum estrogen results in the characteristic features of menopause. Long term effects of low\nestrogen include osteoporosis and vaginal atrophy. After menopause there is a rise in LDL level.\nSerum FSH is elevated (not decreased) in perimenopausal period and causes hot flushes.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"841e1c5bbc8dafbaa9456f5098c1e5a7e98c79d1","duplicate_group_id":"exact-841e1c5bbc8d","duplicate_sources":[{"record_id":"0c54838a69a52dbf39cb","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":818,"source_qid":"89"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
