INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('0c54838a69a52dbf39cb','src-v294-687f312c','89','818','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 48-year-old woman presents complaining of hot flushes, insomnia and mood swings. She has been on sertraline for mood swings and also takes over-the-counter vitamins. Which one of the following is incorrect regarding menopause?',NULL,'C','Menopause is characterized by irregular menstrual cycles and marked hormonal fluctuations, often accompanied by hot flushes, sleep disturbances, mood symptoms, and vaginal dryness.
