INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d9b85a209bd1048faf66','Amedex 2023.pdf','822','Mixed/Unclassified','A 35-year-old woman presents with regular uterine contractions at 34 weeks gestation. Sterile speculum examination is performed showing cervical dilation of 2 cm and intact membranes. Which one of the following investigations is the best
negative predictor of imminent birth within the next 7 days?','{"A":"Transvaginal ultrasound.","B":"Mid-stream urine sample.","C":"The absence of fetal fibronectin in cervical secretions.","D":"The presence of fetal fibronectin in cervical secretions.","E":"Irregular uterine contractions."}','C','Preterm labor is defined as regular uterine contractions after 20 weeks but before 37 weeks gestation, associated with cervical shortening and effacement.
Risk factors for preterm labour include:
Infections
Antepartum hemorrhage
Uterine distension
Spontaneous rupture of membranes
Fetal fibronectin (fFN) is thought to be a "trophoblast glue" that promotes cellular adhesion at uterine-placental and decidual-fetal membrane interfaces. It is released into cervicovaginal secretions when the extracellular matrix of the
chorionic/decidual interface is disrupted; this is the rationale for measurement of fFN as a predictor of PTD.
Absence of fFN in cervical secretions is the most useful negative predictor of imminent birth within the next 7 days. This test is performed at bedside using a commercial test kit according to instructions which are provided by the kit. It is very
expensive but useful.
Candidates for fibronectin test are pregnant women who meet the following criteria:
Intact fetal membranes
Cervical dilation less than 3 cm
Gestational age of between 22 +0d – 34+6d weeks
At 34 weeks gestation, with a cervical dilation of 2 cm and intact membrane fibronectin test is the best negative predictor, meaning that with a negative test, preterm labor within the next 7 days would be unlikely. In the presence of fFN (positive test),
one cannot tell with certainty that preterm labor will follow.
Other steps to take are obtaining vaginal swabs and midstream urine for evaluation of vaginal infection and colonization with group B streptococcus. Ultrasonography is performed to assess cervical length, placental position and presentation before
the fFN is performed. A sterile speculum examination should be considered to exclude rupture of membranes.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"450","duplicate_group_id":"exact-6c51c0f3a1d3","duplicate_sources":[{"record_id":"d9b85a209bd1048faf66","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":822,"source_qid":"450"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"d9b85a209bd1048faf66","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":822,"source_qid":"450","domain_hint":"Mixed/Unclassified","stem":"A 35-year-old woman presents with regular uterine contractions at 34 weeks gestation. Sterile speculum examination is performed showing cervical dilation of 2 cm and intact membranes. Which one of the following investigations is the best\nnegative predictor of imminent birth within the next 7 days?","options":{"A":"Transvaginal ultrasound.","B":"Mid-stream urine sample.","C":"The absence of fetal fibronectin in cervical secretions.","D":"The presence of fetal fibronectin in cervical secretions.","E":"Irregular uterine contractions."},"source_answer":"C","source_explanation":"Preterm labor is defined as regular uterine contractions after 20 weeks but before 37 weeks gestation, associated with cervical shortening and effacement.\nRisk factors for preterm labour include:\nInfections\nAntepartum hemorrhage\nUterine distension\nSpontaneous rupture of membranes\nFetal fibronectin (fFN) is thought to be a \"trophoblast glue\" that promotes cellular adhesion at uterine-placental and decidual-fetal membrane interfaces. It is released into cervicovaginal secretions when the extracellular matrix of the\nchorionic/decidual interface is disrupted; this is the rationale for measurement of fFN as a predictor of PTD.\nAbsence of fFN in cervical secretions is the most useful negative predictor of imminent birth within the next 7 days. This test is performed at bedside using a commercial test kit according to instructions which are provided by the kit. It is very\nexpensive but useful.\nCandidates for fibronectin test are pregnant women who meet the following criteria:\nIntact fetal membranes\nCervical dilation less than 3 cm\nGestational age of between 22 +0d – 34+6d weeks\nAt 34 weeks gestation, with a cervical dilation of 2 cm and intact membrane fibronectin test is the best negative predictor, meaning that with a negative test, preterm labor within the next 7 days would be unlikely. In the presence of fFN (positive test),\none cannot tell with certainty that preterm labor will follow.\nOther steps to take are obtaining vaginal swabs and midstream urine for evaluation of vaginal infection and colonization with group B streptococcus. Ultrasonography is performed to assess cervical length, placental position and presentation before\nthe fFN is performed. A sterile speculum examination should be considered to exclude rupture of membranes.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"6c51c0f3a1d37b6560791d920d55a96706db2d6f","duplicate_group_id":"exact-6c51c0f3a1d3","duplicate_sources":[{"record_id":"d9b85a209bd1048faf66","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":822,"source_qid":"450"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
