INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('e9036fb24c4836e5a01c','Amedex 2023.pdf','837','Mixed/Unclassified','A 28-year old woman visits your office for her first prenatal check-up. She has smokes one pack of cigarettes per day for the past five years. Which one of the following is incorrect regarding disadvantages of smoking during pregnancy?','{"A":"Small for gestational age.","B":"Increased risk of sudden infant death syndrome.","C":"Increased risk of developing small teeth with faulty enamel.","D":"Higher perinatal mortality.","E":"Developmental delay of the baby at least in early years."}','C','Effects of tobacco smoking (active or passive) during pregnancy on fetal, childhood and adult life include:
Preterm labor
Low birth weight
Intrauterine growth restriction
Birth defects – limb reduction, club foot, oral clefts, eye defects, gastrointestinal effects and many other insignificant anomalies
Sudden infant death syndrome (SIDS)
Developmental delay (at least at early stages of development)
Type II diabetes
Obesity
Hypertension
Decreased HDL
Nicotine dependence
Asthma, lower respiratory tract infections
Impaired academic performance and cognitive abilities
Conduct disorders, ADHD, antisocial behaviour
Small teeth and faulty enamel are features seen in fetal alcohol syndrome (FAS), and not smoking.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"509","duplicate_group_id":"exact-78d494c312b5","duplicate_sources":[{"record_id":"e9036fb24c4836e5a01c","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":837,"source_qid":"509"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"e9036fb24c4836e5a01c","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":837,"source_qid":"509","domain_hint":"Mixed/Unclassified","stem":"A 28-year old woman visits your office for her first prenatal check-up. She has smokes one pack of cigarettes per day for the past five years. Which one of the following is incorrect regarding disadvantages of smoking during pregnancy?","options":{"A":"Small for gestational age.","B":"Increased risk of sudden infant death syndrome.","C":"Increased risk of developing small teeth with faulty enamel.","D":"Higher perinatal mortality.","E":"Developmental delay of the baby at least in early years."},"source_answer":"C","source_explanation":"Effects of tobacco smoking (active or passive) during pregnancy on fetal, childhood and adult life include:\nPreterm labor\nLow birth weight\nIntrauterine growth restriction\nBirth defects – limb reduction, club foot, oral clefts, eye defects, gastrointestinal effects and many other insignificant anomalies\nSudden infant death syndrome (SIDS)\nDevelopmental delay (at least at early stages of development)\nType II diabetes\nObesity\nHypertension\nDecreased HDL\nNicotine dependence\nAsthma, lower respirato