INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3f2b0f0f38fcdf602606','Amedex 2023.pdf','844','Mixed/Unclassified','A 28-year-old woman is admitted to the Maternity Unit in early labor. She has had an uncomplicated pregnancy to date and is otherwise healthy. She asks you about fetal monitoring during labor and says she has heard that cardiotocography (CTG) is
helpful for assessment of the baby’s wellbeing and preventing fetal problems. In counselling regarding to the use of CTG as a predictor of fetal outcome and satisfactory labor in comparison to intermittent auscultation and whether CTG monitoring
will reduce the risk of neonatal developmental abnormalities, which one of the following would be the most appropriate advice?','{"A":"There is no evidence to support admission CTG.","B":"CTG is a predictor of previous fetal oxygenation.","C":"Compared to intermittent auscultation, CTG is superior in monitoring the baby’s wellbeing.","D":"CTG is a good predictor of the fetal outcome.","E":"CTG will reduce the risk of neonatal developmental abnormalities."}','A','Continuous fetal heart rate monitoring with CTG is mandatory in all high-risk pregnancies but has been shown to have limited value in low-risk pregnancies. Intermittent fetal heart auscultation has the same efficacy in such pregnancies.
In fact, CTG in low-risk pregnancies, by recognizing abnormalities that are of little if any significance, leads to unnecessary obstetrical interventions such as instrumental delivery or cesarean section.
CTG has not reduced the incidence of neonatal developmental abnormalities such as cerebral palsy. CTG is a predictor of the current fetal condition, not the previous, unless there are severe abnormalities as soon as the CTG is applied on admission.
In conclusion, there is no evidence to support routine admission CTG.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"534","duplicate_group_id":"exact-ea40d1fc217b","duplicate_sources":[{"record_id":"3f2b0f0f38fcdf602606","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":844,"source_qid":"534"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"3f2b0f0f38fcdf602606","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":844,"source_qid":"534","domain_hint":"Mixed/Unclassified","stem":"A 28-year-old woman is admitted to the Maternity Unit in early labor. She has had an uncomplicated pregnancy to date and is otherwise healthy. She asks you about fetal monitoring during labor and says she has heard that cardiotocography (CTG) is\nhelpful for assessment of the baby’s wellbeing and preventing fetal problems. In counselling regarding to the use of CTG as a predictor of fetal outcome and satisfactory labor in comparison to intermittent auscultation and whether CTG monitoring\nwill reduce the risk of neonatal developmental abnormalities, which one of the following would be the most appropriate advice?","options":{"A":"There is no evidence to support admission CTG.","B":"CTG is a predictor of previous fetal oxygenation.","C":"Compared to intermittent auscultation, CTG is superior in monitoring the baby’s wellbeing.","D":"CTG is a good predictor of the fetal outcome.","E":"CTG will reduce the risk of neonatal developmental abnormalities."},"source_answer":"A","source_explanation":"Continuous fetal heart rate monitoring with CTG is mandatory in all high-risk pregnancies but has been shown to have limited value in low-risk pregnancies. Intermittent fetal heart auscultation has the same efficacy in such pregnancies.\nIn fact, CTG in low-risk pregnancies, by recognizing abnormalities that are of little if any significance, leads to unnecessary obstetrical interventions such as instrumental delivery or cesarean section.\nCTG has not reduced the incidence of neonatal developmental abnormalities such as cerebral palsy. CTG is a predictor of the current fetal condition, not the previous, unless there are severe abnormalities as soon as the CTG is applied on admission.\nIn conclusion, there is no evidence to support routine admission CTG.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"ea40d1fc217bf2f8697d5c656e988874a441ac19","duplicate_group_id":"exact-ea40d1fc217b","duplicate_sources":[{"record_id":"3f2b0f0f38fcdf602606","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":844,"source_qid":"534"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk