INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('845a019d54fd692b4796','Amedex 2023.pdf','861','Mixed/Unclassified','Which one of the following is a protective factor against developing uterine fibroids?','{"A":"Obesity.","B":"Early menarche.","C":"Smoking.","D":"First-degree relatives with uterine fibroid.","E":"Nulliparity."}','C','Uterine leiomyoma (fibroid) is a benign uterine tumor commonly seen in females of reproductive age. Fibroid growth is highly dependent on estrogen.
The following are associated with INCREASED risk of uterine leiomyomas:
Black race - the condition is 2- to 3-fold greater in black women than in white women
Family history of uterine leiomyomas
Early menarche
Prenatal exposure to diethylstilbestrol
Obesity - most studies show a relationship between fibroids and increasing body mass index
Significant consumption of beef and other red meats or ham
Consumption of alcohol, especially beer (controversial)
Frequent uterine infections (controversial)
Hypertension (controversial)
The following are associated with DECREASED risk for uterine leiomyomas:
Smoking - by decreasing estrogen levels
Green vegetables and fruit (especially citrus fruit)
Parity (having one or more pregnancies extending beyond 20 weeks) - it has been hypothesized that the postpartum remodeling of the uterus may have the effect of clearing smaller fibroids
Long-acting progestogen
NOTE – Combined oral contraceptive pills (COCPs) do not seem to increase the risk of developing uterine leiomyomas.
Of the given options, smoking is associated with decreased risk of uterine leiomyomas.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"549","duplicate_group_id":"exact-23ab064c8615","duplicate_sources":[{"record_id":"845a019d54fd692b4796","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":861,"source_qid":"549"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"845a019d54fd692b4796","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":861,"source_qid":"549","domain_hint":"Mixed/Unclassified","stem":"Which one of the following is a protective factor against developing uterine fibroids?","options":{"A":"Obesity.","B":"Early menarche.","C":"Smoking.","D":"First-degree relatives with uterine fibroid.","E":"Nulliparity."},"source_answer":"C","source_explanation":"Uterine leiomyoma (fibroid) is a benign uterine tumor commonly seen in females of reproductive age. Fibroid growth is highly dependent on estrogen.\nThe following are associated with INCREASED risk of uterine leiomyomas:\nBlack race - the condition is 2- to 3-fold greater in black women than in white women\nFamily history of uterine leiomyomas\nEarly menarche\nPrenatal exposure to diethylstilbestrol\nObesity - most studies show a relationship between fibroids and increasing body mass index\nSignificant consumption of beef and other red meats or ham\nConsumption of alcohol, especially beer (controversial)\nFrequent uterine infections (controversial)\nHypertension (controversial)\nThe following are associated with DECREASED risk for uterine leiomyomas:\nSmoking - by decreasing estrogen levels\nGreen vegetables and fruit (especially citrus fruit)\nParity (having one or more pregnancies extending beyond 20 weeks) - it has been hypothesized that the postpartum remodeling of the uterus may have the effect of clearing smaller fibroids\nLong-acting progestogen\nNOTE – Combined oral contraceptive pills (COCPs) do not seem to increase the risk of developing uterine leiomyomas.\nOf the given options, smoking is associated with decreased risk of uterine leiomyomas.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","contracept","hypertension","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"23ab064c86150cf187de3e4caa9bc93c3e729b69","duplicate_group_id":"exact-23ab064c8615","duplicate_sources":[{"record_id":"845a019d54fd692b4796","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":861,"source_qid":"549"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
