INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('58ca4bbd75a3d1e2d227','Amedex 2023.pdf','865','Mixed/Unclassified','A 27-year-old woman presents to your clinic complaining of a painful swelling down below. She is unable to sit and feels very uncomfortable. On examination, there is vulval redness and tenderness. Which one of the following you should inspect to
confirm the diagnosis?','{"A":"Posterior end of the labia minora.","B":"Posterior end of the labia majora.","C":"Anterior end of the labia minora.","D":"Anterior end of the labia majora.","E":"Anterior and posterior ends of the labia majora."}','A','Labia minora (singular: labium minus) are two flaps of skin on either side of the vaginal opening situated between the labia majora. They extend from clitoris obliquely downwards, laterally and backwards.
On the front, each lip divides into two portions surrounding around the clitoris. The upper part of each lip passes above the clitoris to meet the upper part of the other lip, forming a fold that overhangs the clitoris called clitoral hood. The posterior
ends of labia minora are joined across the midline by a fold of skin called frenulum of labia minora or fourchette. The part of each lip that is near clitoris is called anterior end of the labium minus (the nomenclature is based on a woman in a standing
position where the clitoris is in the front and fourchette in the back). When a woman is in lithotomy position and the vulva observed anteriorly, the posterior end is in the bottom.
Bartholin glands are two pea-sized glands, each being in the posterior (bottom) part of the labium minus. Observed in the lithotomy view, the glands are approximately at 4 o’clock and 8 o’clock positions. The gland secretions, through a 2- to 2.5-cm
duct, drains into the vestibule. Cysts and abscesses of these glands leads to gland enlargement and tenderness (in case of abscess) felt in the posterior end of the labium minus.
Schematic anatomy of Bartholin''s glands and the ducts and their position in the labia minora -
http://aafp.org
A extensive Bartholin abscess in he left labium minus. The swelling has extended from the posterior end of the labium minus to invlove
almost the entire labium minus - http://emedicine.medscape.com/','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"560","duplicate_group_id":"exact-9f1c83533b6e","duplicate_sources":[{"record_id":"58ca4bbd75a3d1e2d227","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":865,"source_qid":"560"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','low','{"record_id":"58ca4bbd75a3d1e2d227","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":865,"source_qid":"560","domain_hint":"Mixed/Unclassified","stem":"A 27-year-old woman presents to your clinic complaining of a painful swelling down below. She is unable to sit and feels very uncomfortable. On examination, there is vulval redness and tenderness. Which one of the following you should inspect to\nconfirm the diagnosis?","options":{"A":"Posterior end of the labia minora.","B":"Posterior end of the labia majora.","C":"Anterior end of the labia minora.","D":"Anterior end of the labia majora.","E":"Anterior and posterior ends of the labia majora."},"source_answer":"A","source_explanation":"Labia minora (singular: labium minus) are two flaps of skin on either side of the vaginal opening situated between the labia majora. They extend from clitoris obliquely downwards, laterally and backwards.\nOn the front, each lip divides into two portions surrounding around the clitoris. The upper part of each lip passes above the clitoris to meet the upper part of the other lip, forming a fold that overhangs the clitoris called clitoral hood. The posterior\nends of labia minora are joined across the midline by a fold of skin called frenulum of labia minora or fourchette. The part of each lip that is near clitoris is called anterior end of the labium minus (the nomenclature is based on a woman in a standing\nposition where the clitoris is in the front and fourchette in the back). When a woman is in lithotomy position and the vulva observed anteriorly, the posterior end is in the bottom.\nBartholin glands are two pea-sized glands, each being in the posterior (bottom) part of the labium minus. Observed in the lithotomy view, the glands are approximately at 4 o’clock and 8 o’clock positions. The gland secretions, through a 2- to 2.5-cm\nduct, drains into the vestibule. Cysts and abscesses of these glands leads to gland enlargement and tenderness (in case of abscess) felt in the posterior end of the labium minus.\nSchematic anatomy of Bartholin''s glands and the ducts and their position in the labia minora -\nhttp://aafp.org\nA extensive Bartholin abscess in he left labium minus. The swelling has extended from the posterior end of the labium minus to invlove\nalmost the entire labium minus - http://emedicine.medscape.com/","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"low","currentness_keywords":[],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"9f1c83533b6ea2c9b43d8e4e659eaf76c6624c96","duplicate_group_id":"exact-9f1c83533b6e","duplicate_sources":[{"record_id":"58ca4bbd75a3d1e2d227","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":865,"source_qid":"560"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.opti