INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7c0c8df6edff0e91880e','Amedex 2023.pdf','868','Mixed/Unclassified','Which one of the following is highly suggestive of polycystic ovarian syndrome (PCOS)?','{"A":"Elevated FSH.","B":"Elevated LH.","C":"Elevated testosterone levels.","D":"Decreased free testosterone.","E":"Hyperprolactinemia."}','C','Polycystic ovarian syndrome (PCOS) is a common condition associated with the following:
1. Clinical or biochemical hyperandrogenism. Clinical features suggestive of PCOS include hirsutism, acne, deepened voice, etc
2. Menstrual dysfunction, irregularity or lack of ovulation.
3. Polycystic ovaries are present on the ultrasound.
Only the first two mentioned features suffice to establish the diagnosis of PCOS, because cystic structures on ultrasound are often not seen, particularly in women who have been on treatment.
The following hormonal changes are seen in PCOS:
Serum FSH (follicle stimulating hormone) is either normal or low
Elevation of LH (luteinizing hormone)
The LH/FSH ration is a way to differentiate several hormonal abnormalities associated with different conditions. This is best measured on day 3 of the menstrual cycles.
A normal LH/FSH ratio in premenopausal women is about 1:1, while in PCOS this ration may be 2:1 or 3:1. It should be noted that approximately 30% of patients with established diagnosis of PCOS will have a LH/FSH ration of 1:1
Serum estrogen level is either decreased or normal. Overall, estrogen level is very nonspecific.
Serum free testosterone is the first-line investigation in women suspected of having PCOS. Hyperandrogenism is one of the essential criteria to establish the diagnosis of PCOS.
Prolactin level is usually normal or mildly elevated.
​An elevated LH or FHS level can be seen in other conditions such as premature ovarian failure, menopause, etc; therefore, not highly suggestive PCOS.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"562","duplicate_group_id":"exact-15ba0cf38f8c","duplicate_sources":[{"record_id":"7c0c8df6edff0e91880e","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":868,"source_qid":"562"},{"record_id":"5bb469127646ab16e93b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":919,"source_qid":"122"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"7c0c8df6edff0e91880e","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":868,"source_qid":"562","domain_hint":"Mixed/Unclassified","stem":"Which one of the following is highly suggestive of polycystic ovarian syndrome (PCOS)?","options":{"A":"Elevated FSH.","B":"Elevated LH.","C":"Elevated testosterone levels.","D":"Decreased free testosterone.","E":"Hyperprolactinemia."},"source_answer":"C","source_explanation":"Polycystic ovarian syndrome (PCOS) is a common condition associated with the following:\n1. Clinical or biochemical hyperandrogenism. Clinical features suggestive of PCOS include hirsutism, acne, deepened voice, etc\n2. Menstrual dysfunction, irregularity or lack of ovulation.\n3. Polycystic ovaries are present on the ultrasound.\nOnly the first two mentioned features suffice to establish the diagnosis of PCOS, because cystic structures on ultrasound are often not seen, particularly in women who have been on treatment.\nThe following hormonal changes are seen in PCOS:\nSerum FSH (follicle stimulating hormone) is either normal or low\nElevation of LH (luteinizing hormone)\nThe LH/FSH ration is a way to differentiate several hormonal abnormalities associated with different conditions. This is best measured on day 3 of the menstrual cycles.\nA normal LH/FSH ratio in premenopausal women is about 1:1, while in PCOS this ration may be 2:1 or 3:1. It should be noted that approximately 30% of patients with established diagnosis of PCOS will have a LH/FSH ration of 1:1\nSerum estrogen level is either decreased or normal. Overall, estrogen level is very nonspecific.\nSerum free testosterone is the first-line investigation in women suspected of having PCOS. Hyperandrogenism is one of the essential criteria to establish the diagnosis of PCOS.\nProlactin level is usually normal or mildly elevated.\n​An elevated LH or FHS level can be seen in other conditions such as premature ovarian failure, menopause, etc; therefore, not highly suggestive PCOS.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"15ba0cf38f8cacf8301ba508623c68b5d2e48907","duplicate_group_id":"exact-15ba0cf38f8c","duplicate_sources":[{"record_id":"7c0c8df6edff0e91880e","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":868,"source_qid":"562"},{"record_id":"5bb469127646ab16e93b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":919,"source_qid":"122"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
