INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('2f7a9c2981f67a4c3d1b','Amedex 2023.pdf','873','Mixed/Unclassified','A 27-year-old woman, diagnosed with gestational diabetes at 28 weeks pregnancy, has been being managed at a high-risk pregnancy clinic until 38 weeks when she vaginally deliveres a healthy 4-kg baby without any complications. Which one of the
following is correct regarding follow-up?','{"A":"75g oral glucose tolerance test performed between weeks 6 and 12 after delivery.","B":"Check fasting blood glucose level in 6 months after delivery.","C":"HbA1C as soon as possible.","D":"Fasting lipids.","E":"No further action is required."}','A','Less than 10% of women with GDM remain hyperglycemic after delivery. The management of these women requires ongoing care from a diabetes or medical clinic in collaboration with their general practitioner.
The following are recommendations for women with gestational diabetes after delivery:
Checking a random blood glucose level the day after delivery
4-point blood glucose level (BGL) measurement on the day prior to discharge (fasting and two hours post meals for three meals)
Cease blood glucose monitoring if BGL is within normal range.
If there is elevated BGL (above 10 mmol/L) contact the medical registrar / diabetes educator – if BGLs are considerably elevated, after-hours contacts are justified.
It is recommended that women who have had GDM visit their GP for a follow-up oral glucose (75 gr) tolerance test at 6-12 weeks postpartum, and every 1-2 years thereafter.
Lifestyle counselling.
A summary letter is provided to the woman’s GP for follow-up care.
This woman should have a random BGL the day after delivery, 4-point BGL test the day before discharge, and an oral glucose tolerance test using 75g glucose between weeks 6 and 12 after delivery.
Checking HbA1C and fasting lipids would be required if this patient is found to have type 2 diabetes mellitus.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"568","duplicate_group_id":"exact-11f0d0c2ef0d","duplicate_sources":[{"record_id":"2f7a9c2981f67a4c3d1b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":873,"source_qid":"568"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"2f7a9c2981f67a4c3d1b","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":873,"source_qid":"568","domain_hint":"Mixed/Unclassified","stem":"A 27-year-old woman, diagnosed with gestational diabetes at 28 weeks pregnancy, has been being managed at a high-risk pregnancy clinic until 38 weeks when she vaginally deliveres a healthy 4-kg baby without any complications. Which one of the\nfollowing is correct regarding follow-up?","options":{"A":"75g oral glucose tolerance test performed between weeks 6 and 12 after delivery.","B":"Check fasting blood glucose level in 6 months after delivery.","C":"HbA1C as soon as possible.","D":"Fasting lipids.","E":"No further action is required."},"source_answer":"A","source_explanation":"Less than 10% of women with GDM remain hyperglycemic after delivery. The management of these women requires ongoing care from a diabetes or medical clinic in collaboration with their general practitioner.\nThe following are recommendations for women with gestational diabetes after delivery:\nChecking a random blood glucose level the day after delivery\n4-point blood glucose level (BGL) measurement on the day prior to discharge (fasting and two hours post meals for three meals)\nCease blood glucose monitoring if BGL is within normal range.\nIf there is elevated BGL (above 10 mmol/L) contact the medical registrar / diabetes educator – if BGLs are considerably elevated, after-hours contacts are justified.\nIt is recommended that women who have had GDM visit their GP for a follow-up oral glucose (75 gr) tolerance test at 6-12 weeks postpartum, and every 1-2 years thereafter.\nLifestyle counselling.\nA summary letter is provided to the woman’s GP for follow-up care.\nThis woman should have a random BGL the day after delivery, 4-point BGL test the day before discharge, and an oral glucose tolerance test using 75g glucose between weeks 6 and 12 after delivery.\nChecking HbA1C and fasting lipids would be required if this patient is found to have type 2 diabetes mellitus.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","diabetes","management","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"11f0d0c2ef0d6091881419a13b27e264e3f3e9e8","duplicate_group_id":"exact-11f0d0c2ef0d","duplicate_sources":[{"record_id":"2f7a9c2981f67a4c3d1b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":873,"source_qid":"568"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.optio