INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('6f6fb3b9fc9e0490678b','Amedex 2023.pdf','875','Mixed/Unclassified','Which one of the following is increased during pregnancy?','{"A":"Serum alkaline phosphatase.","B":"Serum albumin.","C":"Serum calcium.","D":"Parathyroid hormone.","E":"TSH in the first trimester of pregnancy."}','A','Normal pregnancy is associated with profound changes in almost every organ system to accommodate the demands of the fetoplacental unit.
Serum albumin, transaminases (AST and ALT) and total bilirubin are lowered compared with the non-pregnant state due to expansion of extracellular volume. The only exception is serum alkaline phosphatase (ALP) which is elevated due to ALP of
placental origin.
During pregnancy, the serum total calcium, phosphate and magnesium tend to be low due to the expanded intravascular space. Concentrations of calcium are also affected by the reduced albumin concentration.
The concentration of serum parathyroid hormone tends to be 50% lower in pregnancy, despite the fact that serum concentration of calcium is decreased.
The reasons for hypocalcemia during pregnancy are (1) plasma expansion that through dilutional effect causes decreased plasma calcium and albumin concentration and (2) increased urinary excretion of calcium due to increased GFR
Thyroid stimulating hormone (TSH) normally decreases during the first trimester of pregnancy, during which time there is maximal cross-stimulation of the TSH receptor by human chorionic gonadotropin hormone (HCG).','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"571","duplicate_group_id":"exact-75c1a3a559ad","duplicate_sources":[{"record_id":"6f6fb3b9fc9e0490678b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":875,"source_qid":"571"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"6f6fb3b9fc9e0490678b","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":875,"source_qid":"571","domain_hint":"Mixed/Unclassified","stem":"Which one of the following is increased during pregnancy?","options":{"A":"Serum alkaline phosphatase.","B":"Serum albumin.","C":"Serum calcium.","D":"Parathyroid hormone.","E":"TSH in the first trimester of pregnancy."},"source_answer":"A","source_explanation":"Normal pregnancy is associated with profound changes in almost every organ system to accommodate the demands of the fetoplacental unit.\nSerum albumin, transaminases (AST and ALT) and total bilirubin are lowered compared with the non-pregnant state due to expansion of extracellular volume. The only exception is serum alkaline phosphatase (ALP) which is elevated due to ALP of\nplacental origin.\nDuring pregnancy, the serum total calcium, phosphate and magnesium tend to be low due to the expanded intravascular space. Concentrations of calcium are also affected by the reduced albumin concentration.\nThe concentration of serum parathyroid hormone tends to be 50% lower in pregnancy, despite the fact that serum concentration of calcium is decreased.\nThe reasons for hypocalcemia during pregnancy are (1) plasma expansion that through dilutional effect causes decreased plasma calcium and albumin concentration and (2) increased urinary excretion of calcium due to increased GFR\nThyroid stimulating hormone (TSH) normally decreases during the first trimester of pregnancy, during which time there is maximal cross-stimulation of the TSH receptor by human chorionic gonadotropin hormone (HCG).","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"75c1a3a559ad74df1c8b88bd434eed08bf9428d4","duplicate_group_id":"exact-75c1a3a559ad","duplicate_sources":[{"record_id":"6f6fb3b9fc9e0490678b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":875,"source_qid":"571"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
