INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('01579d064a81c9fdcf62','Amedex 2023.pdf','876','Mixed/Unclassified','A 38-year-old female at 33 weeks’ gestation sustains a road traffic accident at 90 km/hour. In the emergency department and on examination, she is found to be pale, with a heart rate of 112 bpm, blood pressure of 95/55 mmHg and respiratory rate
of 18 breaths per minute. Her oxygen saturation is 95% on room air. Fetal heart rate is audible at 102bpm. The uterus is tense and tender. Which one of the following is the most likely diagnosis?','{"A":"Ruptured uterus.","B":"Liver laceration.","C":"Placental abruption.","D":"Ruptured spleen.","E":"Placenta previa."}','C','This patient has signs and symptoms consistent with clinical diagnosis of placental abruption.
Trauma in last trimester of pregnancy could be dangerous to both the mother and the fetus. Motor vehicle accidents, by force of deceleration, cause placental separation.
Placental abruption is characterized by painful, tender uterus which is often contracting. The condition leads to maternal hypovolemic hypotension and consequent fetal distress represented by fetal bradycardia and repetitive late decelerations.
The amount of vaginal bleeding is not usually an appropriate indicator to severity of placental abruption, because bleeding could be very severe or it may be concealed between uterine wall and placenta in form of a hematoma.
(Option A) Uterine rupture is characterized by severe abdominal pain and tenderness, cessation of contractions and loss of uterine tone. It is associated with mild to moderate vaginal bleeding and fetal bradycardia or loss of heart sound. Compared
to placental abruption, there uterus is less tense and tender.
(Options B and D) Ruptured spleen and liver laceration present may justify the low blood pressure, tachycardia and fetal bradycardia but not the tense, tender and contracting uterus.
(Option E) Placenta previa presents with sudden, painless bleeding with bright red blood. There is no uterine tenderness. This diagnosis is not consistent with the clinical picture.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"572","duplicate_group_id":"exact-dbf842f21579","duplicate_sources":[{"record_id":"01579d064a81c9fdcf62","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":876,"source_qid":"572"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"01579d064a81c9fdcf62","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":876,"source_qid":"572","domain_hint":"Mixed/Unclassified","stem":"A 38-year-old female at 33 weeks’ gestation sustains a road traffic accident at 90 km/hour. In the emergency department and on examination, she is found to be pale, with a heart rate of 112 bpm, blood pressure of 95/55 mmHg and respiratory rate\nof 18 breaths per minute. Her oxygen saturation is 95% on room air. Fetal heart rate is audible at 102bpm. The uterus is tense and tender. Which one of the following is the most likely diagnosis?","options":{"A":"Ruptured uterus.","B":"Liver laceration.","C":"Placental abruption.","D":"Ruptured spleen.","E":"Placenta previa."},"source_answer":"C","source_explanation":"This patient has signs and symptoms consistent with clinical diagnosis of placental abruption.\nTrauma in last trimester of pregnancy could be dangerous to both the mother and the fetus. Motor vehicle accidents, by force of deceleration, cause placental separation.\nPlacental abruption is characterized by painful, tender uterus which is often contracting. The condition leads to maternal hypovolemic hypotension and consequent fetal distress represented by fetal bradycardia and repetitive late decelerations.\nThe amount of vaginal bleeding is not usually an appropriate indicator to severity of placental abruption, because bleeding could be very severe or it may be concealed between uterine wall and placenta in form of a hematoma.\n(Option A) Uterine rupture is characterized by severe abdominal pain and tenderness, cessation of contractions and loss of uterine tone. It is associated with mild to moderate vaginal bleeding and fetal bradycardia or loss of heart sound. Compared\nto placental abruption, there uterus is less tense and tender.\n(Options B and D) Ruptured spleen and liver laceration present may justify the low blood pressure, tachycardia and fetal bradycardia but not the tense, tender and contracting uterus.\n(Option E) Placenta previa presents with sudden, painless bleeding with bright red blood. There is no uterine tenderness. This diagnosis is not consistent with the clinical picture.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"dbf842f21579edffd4cecfa358d86c4f92483ba3","duplicate_group_id":"exact-dbf842f21579","duplicate_sources":[{"record_id":"01579d064a81c9fdcf62","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":876,"source_qid":"572"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
