INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('8ea390567f02fa10c494','Amedex 2023.pdf','883','Mixed/Unclassified','Which one of the following is not elevated in the third trimester of pregnancy?','{"A":"Serum prolactin.","B":"Serum alkaline phosphatase.","C":"Serum iron binding capacity.","D":"Serum free T4.","E":"Serum cortisol."}','D','Normally, estrogen stimulates and progesterone inhibits prolactin secretion; despite this action and counteraction, there is a slight raise in prolactin level throughout pregnancy.
Serum alkaline phosphatase is increased in pregnancy due to placental ALP.
Physiologically, the concentration of thyroid stimulating hormone (TSH) normally decreases during the first trimester of pregnancy when there is maximal cross-stimulation of the TSH receptor by hCG. The TSH concentration then returns to its pre-
pregnancy level in the second trimester and then rises slightly in the third trimester. However, most of changes still occur within the normal non-pregnant range. Serum free T3 and T4 concentrations remain essentially unchanged during pregnancy
but total concentrations, which include both free and protein-bound fractions, are significantly elevated due to increased circulating binding globulins..
Iron binding capacity reflects the protein used for iron transport, transferrin. Transferrin is a globulin in the beta band on electrophoresis. Both transferrin and iron binding capacity are elevated in pregnancy to counteract decreased plasma iron during
pregnancy.
Cortisol levels can be elevated up to three times normal when compared to non-pregnant levels.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"578","duplicate_group_id":"exact-f36667c0f7af","duplicate_sources":[{"record_id":"8ea390567f02fa10c494","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":883,"source_qid":"578"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"8ea390567f02fa10c494","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":883,"source_qid":"578","domain_hint":"Mixed/Unclassified","stem":"Which one of the following is not elevated in the third trimester of pregnancy?","options":{"A":"Serum prolactin.","B":"Serum alkaline phosphatase.","C":"Serum iron binding capacity.","D":"Serum free T4.","E":"Serum cortisol."},"source_answer":"D","source_explanation":"Normally, estrogen stimulates and progesterone inhibits prolactin secretion; despite this action and counteraction, there is a slight raise in prolactin level throughout pregnancy.\nSerum alkaline phosphatase is increased in pregnancy due to placental ALP.\nPhysiologically, the concentration of thyroid stimulating hormone (TSH) normally decreases during the first trimester of pregnancy when there is maximal cross-stimulation of the TSH receptor by hCG. The TSH concentration then returns to its pre-\npregnancy level in the second trimester and then rises slightly in the third trimester. However, most of changes still occur within the normal non-pregnant range. Serum free T3 and T4 concentrations remain essentially unchanged during pregnancy\nbut total concentrations, which include both free and protein-bound fractions, are significantly elevated due to increased circulating binding globulins..\nIron binding capacity reflects the protein used for iron transport, transferrin. Transferrin is a globulin in the beta band on electrophoresis. Both transferrin and iron binding capacity are elevated in pregnancy to counteract decreased plasma iron during\npregnancy.\nCortisol levels can be elevated up to three times normal when compared to non-pregnant levels.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"f36667c0f7afa4ed772c8cae198ddf6dbb9e3f48","duplicate_group_id":"exact-f36667c0f7af","duplicate_sources":[{"record_id":"8ea390567f02fa10c494","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":883,"source_qid":"578"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
