INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('05a8bbb13df836d309a2','Amedex 2023.pdf','890','Mixed/Unclassified','A 35-year-old woman develops deep vein thrombosis (DVT) of her left lower leg at 20 weeks pregnancy. Which one of the following statements is true regarding DVT in pregnancy?','{"A":"Decreased levels of protein C and S is a precipitating factor.","B":"DVT of right leg is more common than left leg.","C":"Decreased levels of factor V and Vll is a precipitating factor.","D":"Deep vein thrombosis is a rare condition in pregnancy.","E":"Warfarin is the treatment of choice."}','A','Pregnancy is considered a hypercoagulable state caused by a decrease in anticoagulation activity due to a drop in proteins C and S, and an increase in activity of pro-coagulants, factor V and Vll.
Such physiological changes make DVT a common complication in pregnancy with an incidence rate of 1 in 2200 of pregnancies in Australia.
In pregnant women, deep vein thrombosis occurs much more commonly in the left leg than in the right leg (85%) due to compression of the left iliac vein by the pregnant uterus.
Anticoagulant therapy with low-molecular weight heparin (LMWH) or unfractionated heparin is the treatment of choice in pregnant women with DVT.
Warfarin therapy is contraindicated throughout pregnancy due to association with fetal warfarin syndrome and increased risk of fetal intracranial hemorrhage in the second and third trimesters.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"583","duplicate_group_id":"exact-e8cebf515a7a","duplicate_sources":[{"record_id":"05a8bbb13df836d309a2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":890,"source_qid":"583"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"05a8bbb13df836d309a2","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":890,"source_qid":"583","domain_hint":"Mixed/Unclassified","stem":"A 35-year-old woman develops deep vein thrombosis (DVT) of her left lower leg at 20 weeks pregnancy. Which one of the following statements is true regarding DVT in pregnancy?","options":{"A":"Decreased levels of protein C and S is a precipitating factor.","B":"DVT of right leg is more common than left leg.","C":"Decreased levels of factor V and Vll is a precipitating factor.","D":"Deep vein thrombosis is a rare condition in pregnancy.","E":"Warfarin is the treatment of choice."},"source_answer":"A","source_explanation":"Pregnancy is considered a hypercoagulable state caused by a decrease in anticoagulation activity due to a drop in proteins C and S, and an increase in activity of pro-coagulants, factor V and Vll.\nSuch physiological changes make DVT a common complication in pregnancy with an incidence rate of 1 in 2200 of pregnancies in Australia.\nIn pregnant women, deep vein thrombosis occurs much more commonly in the left leg than in the r