INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('7555b499e9bff52b3a59','Amedex 2023.pdf','891','Mixed/Unclassified','A 30-year-old woman developed deep vein thrombosis at 30 weeks pregnancy and was started on the therapeutic dose of low molecular weight heparin (LMWH). Now and at 34 weeks gestation, she is in your office for a follow-up visit. Her expected
date of delivery is due in 4 weeks. Which one of the following would be the best advice for her today?','{"A":"The LMWH should be replaced with unfractionated heparin.","B":"Continue the LMWH until delivery.","C":"Switch to warfarin and check INR in 2 days.","D":"Add warfarin to the LMWH.","E":"Cease anticoagulation."}','A','A patient with deep vein thrombosis during pregnancy requires 3-6 months of treatment with therapeutic dose of LMWH or subcutaneous unfractionated heparin (UFH). The duration of therapy depends on the site of the thrombosis.
LMWH may be associated with an increased risk of epidural hematoma in women receiving epidural anesthesiae in labor; therefore, it is recommended that it be switched to subcutaneous UFH at 36 weeks or sooner if delivery is expected earlier to
make regional anesthesia at labor (if indicated) safe.
Subcutaneous UFH can be discontinued 24-36 hours prior to anticipated delivery or induction. If there is high risk of thromboembolism in the absence of anticoagulation, the patient can be started on intravenous UFH because it has a shorter half-life.
Intravenous UFH can be discontinued 4-6 hours before delivery.
Prior to neuraxial anesthesia, an ATTP should be checked.
Anticoagulation can be restarted with UFH or LMWH 4 to 6 hours after vaginal delivery or 6-12 hours after cesarean delivery. If a neuraxial catheter was used, anticoagulation should not be restarted for at least 12 hours after it is removed.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"584","duplicate_group_id":"exact-d7df9fd93cb3","duplicate_sources":[{"record_id":"7555b499e9bff52b3a59","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":891,"source_qid":"584"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"7555b499e9bff52b3a59","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":891,"source_qid":"584","domain_hint":"Mixed/Unclassified","stem":"A 30-year-old woman developed deep vein thrombosis at 30 weeks pregnancy and was started on the therapeutic dose of low molecular weight heparin (LMWH). Now and at 34 weeks gestation, she is in your office for a follow-up visit. Her expected\ndate of delivery is due in 4 weeks. Which one of the following would be the best advice for her today?","options":{"A":"The LMWH should be replaced with unfractionated heparin.","B":"Continue the LMWH until delivery.","C":"Switch to warfarin and check INR in 2 days.","D":"Add warfarin to the LMWH.","E":"Cease anticoagulation."},"source_answer":"A","source_explanation":"A patient with deep vein thrombosis during pregnancy requires 3-6 months of treatment with therapeutic dose of LMWH or subcutaneous unfractionated heparin (UFH). The duration of therapy depends on the site of the thrombosis.\nLMWH may be associated with an increased risk of epidural hematoma in women receiving epidural anesthesiae in labor; therefore, it is recommended that it be switched to subcutaneous UFH at 36 weeks or sooner if delivery is expected earlier to\nmake regional anesthesia at labor (if indicated) safe.\nSubcutaneous UFH can be discontinued 24-36 hours prior to anticipated delivery or induction. If there is high risk of thromboembolism in the absence of anticoagulation, the patient can be started on intravenous UFH because it has a shorter half-life.\nIntravenous UFH can be discontinued 4-6 hours before delivery.\nPrior to neuraxial anesthesia, an ATTP should be checked.\nAnticoagulation can be restarted with UFH or LMWH 4 to 6 hours after vaginal delivery or 6-12 hours after cesarean delivery. If a neuraxial catheter was used, anticoagulation should not be restarted for at least 12 hours after it is removed.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["anticoag","dose","duration","pregnan","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"d7df9fd93cb33773ade2a1c5bad8c6e5c84ddacb","duplicate_group_id":"exact-d7df9fd93cb3","duplicate_sources":[{"record_id":"7555b499e9bff52b3a59","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":891,"source_qid":"584"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.