INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('61f918b8a9fdb4fe3dd0','Amedex 2023.pdf','898','Mixed/Unclassified','An 18-week pregnat woman is brought to the Emergency Department with complaint of sudden-onset severe frontal headache. On examination, she has a blood pressure of 80/60 mmHg, pulse of 110bpm, respiratory rate of 17 breaths per minute
and temperature of 37.3°C. The rest of the examination is unremarkable. There is no neck stiffness, abdominal pain or tenderness, or uterine contractions. Which one of the following is the investigation more likely to establish the diagnosis?','{"A":"Lumbar puncture.","B":"CT scan of the head.","C":"Ultrasonography.","D":"MRI of the head.","E":"Full blood exam (FBE) and liver function tests (LFT)."}','D','With the clinical findings of frontal headache and hypotension in a pregnant woman, pituitary apoplexy should be considered as one of the most important differential diagnoses. Pituitary apoplexy is defined as sudden hemorrhage into the pituitary
gland. Hemorrhage often occurs into a pituitary adenoma.
The most dramatic presentation of apoplexy is the sudden onset of excruciating headache, diplopia due to pressure on the oculomotor nerve, and hypopituitarism.
All pituitary hormonal deficiencies can occur, but a fall in ACTH and, consequently, cortisol is most serious because it can cause life-threatening hypotension.
In a series of 35 patients with pituitary apoplexy seen at one center, 97% had headache, 71% had visual field impairment, and 66% had decreased visual acuity. Only a minority had clinical manifestations of hormonal excess or deficiency, but there
was biochemical evidence of gonadotropin deficiency in 79%, ACTH deficiency in 76%, and TSH deficiency in 50%.
CT scan and MRI can be used for detection of intra-pituitary hemorrhage; however, MRI is more sensitive for evaluation of the pituitary gland.
Hypopituitarism and the diplopia may improve after surgical decompression of the pituitary. Both problems may also improve spontaneously as the blood is absorbed over a course of weeks to months after the hemorrhage.
For hypotension, high-dose corticosteroids are the mainstay of therapy.
(Options A and B) With headache and hypotension, subarachnoid hemorrhage can be another differential diagnoses, but headache of SAH tends to be much more severe (the worst headache in life) and often associated with neck stiffness. On the
other hand, skull cannot accommodate enough blood to justify the hypotension and the tachycardia in this patient. CT scan of the head (non-contrast) and LP (if CT was inconclusive) are used if SAH is suspected.
(Option C) Ultrasonography is of no use in assessment of this patient with a possible intracranial pathology.
(Option E) Preeclampsia is defined as persistent hypertension and proteinuria after 20 weeks’ gestation. FBE, LFT, and urinalysis should be considered for excluding preeclampsia. This woman with hypotension is less likely to have preeclampsia.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"592","duplicate_group_id":"exact-6afef1aed088","duplicate_sources":[{"record_id":"61f918b8a9fdb4fe3dd0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":898,"source_qid":"592"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"61f918b8a9fdb4fe3dd0","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":898,"source_qid":"592","domain_hint":"Mixed/Unclassified","stem":"An 18-week pregnat woman is brought to the Emergency Department with complaint of sudden-onset severe frontal headache. On examination, she has a blood pressure of 80/60 mmHg, pulse of 110bpm, respiratory rate of 17 breaths per minute\nand temperature of 37.3°C. The rest of the examination is unremarkable. There is no neck stiffness, abdominal pain or tenderness, or uterine contractions. Which one of the following is the investigation more likely to establish the diagnosis?","options":{"A":"Lumbar puncture.","B":"CT scan of the head.","C":"Ultrasonography.","D":"MRI of the head.","E":"Full blood exam (FBE) and liver function tests (LFT)."},"source_answer":"D","source_explanation":"With the clinical findings of frontal headache and hypotension in a pregnant woman, pituitary apoplexy should be considered as one of the most important differential diagnoses. Pituitary apoplexy is defined as sudden hemorrhage into the pituitary\ngland. Hemorrhage often occurs into a pituitary adenoma.\nThe most dramatic presentation of apoplexy is the sudden onset of excruciating headache, diplopia due to pressure on the oculomotor nerve, and hypopituitarism.\nAll pituitary hormonal deficiencies can occur, but a fall in ACTH and, consequently, cortisol is most serious because it can cause life-threatening hypotension.\nIn a series of 35 patients with pituitary apoplexy seen at one center, 97% had headache, 71% had visual field impairment, and 66% had decreased visual acuity. Only a minority had clinical manifestations of hormonal excess or deficiency, but there\nwas biochemical evidence of gonadotropin deficiency in 79%, ACTH deficiency in 76%, and TSH deficiency in 50%.\nCT scan and MRI can be used for detection of intra-pituitary hemorrhage; however, MRI is more sensitive for evaluation of the pituitary gland.\nHypopituitarism and the diplopia may improve after surgical decompression of the pituitary. Both problems may also improve spontaneously as the blood is absorbed over a course of weeks to months after the hemorrhage.\nFor hypotension, high-dose corticosteroids are the mainstay of therapy.\n(Options A and B) With headache and hypotension, subarachnoid hemorrhage can be another differential diagnoses, but headache of SAH tends to be much more severe (the worst headache in life) and often associated with neck stiffness. On the\nother hand, skull cannot accommodate enough blood to justify the hypotension and the tachycardia in this patient. CT scan of the head (non-contrast) and LP (if CT was inconclusive) are used if SAH is suspected.\n(Option C) Ultrasonography is of no use in assessment of this patient with a possible intracranial pathology.\n(Option E) Preeclampsia is defined as persistent hypertension and proteinuria after 20 weeks’ gestation. FBE, LFT, and urinalysis should be considered for excluding preeclampsia. This woman with hypotension is less likely to have preeclampsia.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","dose","hypertension","pregnan","therapy"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"6afef1aed088ae4cb41259d9ad231788f85ffd25","duplicate_group_id":"exact-6afef1aed088","duplicate_sources":[{"record_id":"61f918b8a9fdb4fe3dd0","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":898,"source_qid":"592"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
