INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('439b5495d2c3d03f0ed1','Amedex 2023.pdf','901','Mixed/Unclassified','A 25-year-old pregnant woman comes to your clinic with vaginal bleeding at 14 weeks’ gestation. Which one of the following is the main reason for performing ultrasonography?','{"A":"Excluding ectopic pregnancy.","B":"Excluding neural tube defects.","C":"Determining the cause of bleeding.","D":"Determining if the fetus is alive.","E":"Excluding congenital heart defects."}','C','Transvaginal ultrasound is the cornerstone in evaluation of vaginal bleeding in the second trimester. The main reason for ultrasonography is to find an underlying cause for the bleeding. Reasons to perform an ultrasound include:
To determine whether the placenta is covering the cervical os (placenta previa).
Whether there is evidence of decidual hemorrhage causing placental separation (abruption of placenta)
Whether the cervix shows signs suggestive of cervical insufficiency (short length, dilated internal os, funneling of the fetal membranes).
Whether there is a cervical polyp
The common causes of vaginal bleeding in second and third trimesters of pregnancy are:
Bloody show associated with cervical insufficiency or labor
Placenta previa
Placental abruption
Uterine rupture
Vasa previa','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"595","duplicate_group_id":"exact-833eda18835d","duplicate_sources":[{"record_id":"439b5495d2c3d03f0ed1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":901,"source_qid":"595"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','medium','{"record_id":"439b5495d2c3d03f0ed1","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":901,"source_qid":"595","domain_hint":"Mixed/Unclassified","stem":"A 25-year-old pregnant woman comes to your clinic with vaginal bleeding at 14 weeks’ gestation. Which one of the following is the main reason for performing ultrasonography?","options":{"A":"Excluding ectopic pregnancy.","B":"Excluding neural tube defects.","C":"Determining the cause of bleeding.","D":"Determining if the fetus is alive.","E":"Excluding congenital heart defects."},"source_answer":"C","source_explanation":"Transvaginal ultrasound is the cornerstone in evaluation of vaginal bleeding in the second trimester. The main reason for ultrasonography is to find an underlying cause for the bleeding. Reasons to perform an ultrasound include:\nTo determine whether the placenta is covering the cervical os (placenta previa).\nWhether there is evidence of decidual hemorrhage causing placental separation (abruption of placenta)\nWhether the cervix shows signs suggestive of cervical insufficiency (short length, dilated internal os, funneling of the fetal membranes).\nWhether there is a cervical polyp\nThe common causes of vaginal bleeding in second and third trimesters of pregnancy are:\nBloody show associated with cervical insufficiency or labor\nPlacenta previa\nPlacental abruption\nUterine rupture\nVasa previa","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"medium","currentness_keywords":["age","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"833eda18835da3eb9f107fde2438a2cc2ca7809d","duplicate_group_id":"exact-833eda18835d","duplicate_sources":[{"record_id":"439b5495d2c3d03f0ed1","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":901,"source_qid":"595"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
