INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('24b66a8b920331f65b1b','Amedex 2023.pdf','904','Mixed/Unclassified','Which of the following is not a risk factor for isolated spontaneous abortion?','{"A":"Age more than 35 years.","B":"Cigarette smoking.","C":"High doses of caffeine.","D":"Uterine adhesions.","E":"Retroverted uterus."}','E','The following are known risk factors for spontaneous abortion or miscarriage:
Advanced maternal age (≥35)
Previous miscarriage(s)
Antiphospholipid syndrome
Parentral chromosomal derangements
Embryonic chromosomal abnormalities
Congenital uterine malformations
Cervical weakness
Diabetes mellitus (subclinical disease excluded) and thyroid disease (subclinical disease excluded)
Immune factors
Infections
Inherited thrombophilic defects
Caffeine, smoking and alcohol use (dose dependent)
A retroverted uterus has not shown association with increased risk of spontaneous abortions. A retroverted uterus is a uterus that is tilted backwards instead of forwards.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"598","duplicate_group_id":"exact-26f353cd5a56","duplicate_sources":[{"record_id":"24b66a8b920331f65b1b","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":904,"source_qid":"598"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"24b66a8b920331f65b1b","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":904,"source_qid":"598","domain_hint":"Mixed/Unclassified","stem":"Which of the following is not a risk factor for isolated spontaneous abortion?","options":{"A":"Age more than 35 years.","B":"Cigarette smoking.","C":"High doses of caffeine.","D":"Uterine adhesions.","E":"Retroverted uterus."},"source_answer":"E","source_explanation":"The following are known risk factors for spontaneous abortion or miscarriage:\nAdvanced maternal age (≥35)\nPrevious miscarriage(s)\nAntiphospholipid syndrome\nParentral chromosomal derangements\nEmbryonic chromosomal abnormalities\nCongenital uterine malformations\nCervical weakness\nDiabetes mellitus (subclinical disease excluded) and thyroid disease (subclinical disease excluded)\nImmune factors\nInfections\nInherited thrombophilic defects\nCaffeine, smoking and alcohol use (dose dependent)\nA retroverted uterus has not shown association with increased risk of spontaneous abortions. A retroverted uterus is a uterus that is tilted backwards instead of forwards.","source_answer_status":"present","