INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('3687da22cd6cb8f32a7a','Amedex 2023.pdf','905','Mixed/Unclassified','A 24-year-old woman underwent dilation and curettage for septic abortion. Now, she has developed amenorrhea of six months duration. An office pregnancy test excludes pregnancy. She smokes 10 cigarettes and drinks two standard units of
alcohol every day. Which one of the following is the most appropriate next investigation to reach a cause for this presentation?','{"A":"Liver function tests.","B":"Urine analysis and microscopy.","C":"Transvaginal ultrasound.","D":"Full hormone assay.","E":"MRI of the brain."}','C','Intrauterine adhesions are a common complication of curettage. Approximately 90% cases of severe intrauterine adhesions are related to curettage for pregnancy complications such as missed or incomplete abortion, postpartum hemorrhage, or
retained placental tissue.
Intrauterine adhesions can be asymptomatic and of no clinical significance. If there are symptoms they can include:
Infertility
Menstrual irregularities (amenorrhea)
Cyclic pelvic pain
Recurrent miscarriages
When intrauterine adhesions are suspected, transvaginal ultrasonography is the next best investigation to confirm the diagnosis. Although not always necessary, diagnostic hysteroscopy remains the gold standard diagnostic investigation.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"599","duplicate_group_id":"exact-08743bb41c90","duplicate_sources":[{"record_id":"3687da22cd6cb8f32a7a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":905,"source_qid":"599"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"3687da22cd6cb8f32a7a","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":905,"source_qid":"599","domain_hint":"Mixed/Unclassified","stem":"A 24-year-old woman underwent dilation and curettage for septic abortion. Now, she has developed amenorrhea of six months duration. An office pregnancy test excludes pregnancy. She smokes 10 cigarettes and drinks two standard units of\nalcohol every day. Which one of the following is the most appropriate next investigation to reach a cause for this presentation?","options":{"A":"Liver function tests.","B":"Urine analysis and microscopy.","C":"Transvaginal ultrasound.","D":"Full hormone assay.","E":"MRI of the brain."},"source_answer":"C","source_explanation":"Intrauterine adhesions are a common complication of curettage. Approximately 90% cases of severe intrauterine adhesions are related to curettage for pregnancy complications such as missed or incomplete abortion, postpartum hemorrhage, or\nretained placental tissue.\nIntrauterine adhesions can be asymptomatic and of no clinical significance. If there are symptoms they can include:\nInfertility\nMenstrual irregularities (amenorrhea)\nCyclic pelvic pain\nRecurrent miscarriages\nWhen intrauterine adhesions are suspected, transvaginal ultrasonography is the next best investigation to confirm the diagnosis. Although not always necessary, diagnostic hysteroscopy remains the gold standard diagnostic investigation.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","duration","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"08743bb41c90f61abc1343a5a39cc4847493ad71","duplicate_group_id":"exact-08743bb41c90","duplicate_sources":[{"record_id":"3687da22cd6cb8f32a7a","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":905,"source_qid":"599"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
