INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d01d677e604beed16481','Amedex 2023.pdf','929','Mixed/Unclassified','A30-year-old woman on oral contraceptive pills (Microgynon 30®) presents to your clinic for a repeat prescription. On examination, you find out that she has a blood pressure of
160/100mmHg, confirmed by a second reading 20 minutes later. She mentions that her husband and she are planning to become pregnant in 6 months. Which one of the following
is the best advice for her?','{"A":"She can continue the same OCP but should use methyldopa for hypertension.","B":"She should change to an OCP preparation with lower dose of estrogen.","C":"She should stop OCP, use condoms for contraception and reassess her blood pressure in 3 months.","D":"She should stop the OCP and be started on methyldopa for hypertension.","E":"She should stop the OCP and be started on a diuretic or ACE inhibitor for hypertension."}','C','Eestrogen-containing hormonal contraception methods are NOT absolutely contraindicated in hypertensive women, whether the hypertension has existed before or developed as
result of the hormonal contraception use. With hypertension, the patient should be started on appropriate antihypertensive agent if she insists on using the method.
This woman, however, is willing to stop the OCP; hence, cessation of the estrogen-containing method and using an alternative is the best advice. Since this woman is planning to
conceive, using condoms for contraception in the next 6 month, during which she does not want to become pregnant, would be the best advice among the options.
If OCPs are ceased, she does not need to be started on antihypertensive drugs at this stage because with cessation of estrogen, there is a good chance that her blood pressure
returns to normal. Antihypertensive medications will be indicated if blood pressure remains high despite stopping the OCP.
If use of antihypertensive medications is inevitable, methyldopa should be considered as first line because it is safe to use during pregnancy.
ACE inhibitors and diuretics are contraindicated during pregnancy and should be avoided.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"662","duplicate_group_id":"exact-eaf067067acc","duplicate_sources":[{"record_id":"d01d677e604beed16481","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":929,"source_qid":"662"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d01d677e604beed16481","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":929,"source_qid":"662","domain_hint":"Mixed/Unclassified","stem":"A30-year-old woman on oral contraceptive pills (Microgynon 30®) presents to your clinic for a repeat prescription. On examination, you find out that she has a blood pressure of\n160/100mmHg, confirmed by a second reading 20 minutes later. She mentions that her husband and she are planning to become pregnant in 6 months. Which one of the following\nis the best advice for her?","options":{"A":"She can continue the same OCP but should use methyldopa for hypertension.","B":"She should change to an OCP preparation with lower dose of estrogen.","C":"She should stop OCP, use condoms for contraception and reassess her blood pressure in 3 months.","D":"She should stop the OCP and be started on methyldopa for hypertension.","E":"She should stop the OCP and be started on a diuretic or ACE inhibitor for hypertension."},"source_answer":"C","source_explanation":"Eestrogen-containing hormonal contraception methods are NOT absolutely contraindicated in hypertensive women, whether the hypertension has existed before or developed as\nresult of the hormonal contraception use. With hypertension, the patient should be started on appropriate antihypertensive agent if she insists on using the method.\nThis woman, however, is willing to stop the OCP; hence, cessation of the estrogen-containing method and using an alternative is the best advice. Since this woman is planning to\nconceive, using condoms for contraception in the next 6 month, during which she does not want to become pregnant, would be the best advice among the options.\nIf OCPs are ceased, she does not need to be started on antihypertensive drugs at this stage because with cessation of estrogen, there is a good chance that her blood pressure\nreturns to normal. Antihypertensive medications will be indicated if blood pressure remains high despite stopping the OCP.\nIf use of antihypertensive medications is inevitable, methyldopa should be considered as first line because it is safe to use during pregnancy.\nACE inhibitors and diuretics are contraindicated during pregnancy and should be avoided.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","contracept","drug","hypertension","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"eaf067067accd019dc6f3495a09362dce8333ea9","duplicate_group_id":"exact-eaf067067acc","duplicate_sources":[{"record_id":"d01d677e604beed16481","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":929,"source_qid":"662"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
