INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('d01d677e604beed16481','src-v294-687f312c','662','929','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A30-year-old woman on oral contraceptive pills (Microgynon 30®) presents to your clinic for a repeat prescription. On examination, you find out that she has a blood pressure of
160/100mmHg, confirmed by a second reading 20 minutes later. She mentions that her husband and she are planning to become pregnant in 6 months. Which one of the following
is the best advice for her?',NULL,'C','Eestrogen-containing hormonal contraception methods are NOT absolutely contraindicated in hypertensive women, whether the hypertension has existed before or developed as
result of the hormonal contraception use. With hypertension, the patient should be started on appropriate antihypertensive agent if she insists on using the method.
This woman, however, is willing to stop the OCP; hence, cessation of the estrogen-containing method and using an alternative is the best advice. Since this woman is planning to
conceive, using condoms for contraception in the next 6 month, during which she does not want to become pregnant, would be the best advice among the options.
If OCPs are ceased, she does not need to be started on antihypertensive drugs at this stage because with cessation of estrogen, there is a good chance that her blood pressure
returns to normal. Antihypertensive medications will be indicated if blood pressure remains high despite stopping the OCP.
If use of antihypertensive medications is inevitable, methyldopa should be considered as first line because it is safe to use during pregnancy.
ACE inhibitors and diuretics are contraindicated during pregnancy and should be avoided.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"662","duplicate_group_id":"exact-eaf067067acc","duplicate_sources":[{"record_id":"d01d677e604beed16481","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":929,"source_qid":"662"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
