INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('51ef97fab6487a55d958','Amedex 2023.pdf','930','Mixed/Unclassified','A 51-year-old menopausal woman presents with frequent hot flushes disturbing her sleep and occupational performance. She has the history of breast cancer diagnosed 10 years ago. The umor was positive for estrogen receptors on pathology.
Which one of the following would be the most appropriate management?','{"A":"Cyclical estrogen and progesterone.","B":"Progesterone-only HRT.","C":"Paroxetine.","D":"Black cohoch.","E":"Mefenamic acid."}','C','Hot flush is a sudden feeling of warmth that is generally most intense over the face, neck, and chest. The duration is variable but on average lasts about 3-4 minutes. It is often accompanied by sweating that can be profuse and followed by a chill.
Hot flushes are seen in perimenopausal women as one of the most common complaints, and is the only indication to start hormone replacement therapy (HRT). HRT is the most effective treatment for severe hot flushes and is a reasonable choice in
the absence of contraindications.
(Options A and B) Hormonal therapy including estrogen and progesterone is avoided in patients with history of breast cancer, although the effect of progesterone on breast cancer is not established.
Women with hot flushes and contraindications to hormonal therapy may benefit from selective serotonin reuptake inhibitor (first-line) such as paroxetine, or other medications such as gabapentin or velnafaxine.
SSRI are widely used in Australia for management of hot flushes when there is contraindication to hormone therapy. It also improves mood symptoms. Paroxetine is the most common prescribed SSRI (and the only one approved by FDA in US). SSRIs
are not as effective as HRT, but definitely more effective than placebo. It is important to note that paroxetine, fluoxetine, duloxetine, and bupropion should not be used in patients who are currently on tamoxifen because it interferes with the
conversion of tamoxifen to its active metabolite endoxifen.
(Option D) Black Cohosh acts by unknown mechanism and is used for hot flushes. Many studies have found no significant benefit over placebo.
(Option E) Mefenamic acid may help for short-term control of menopausal symptoms; however, its long term use is controversial and not recommended.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":null,"duplicate_group_id":"exact-68d161de2fcf","duplicate_sources":[{"record_id":"51ef97fab6487a55d958","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":930,"source_qid":null}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"51ef97fab6487a55d958","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":930,"source_qid":null,"domain_hint":"Mixed/Unclassified","stem":"A 51-year-old menopausal woman presents with frequent hot flushes disturbing her sleep and occupational performance. She has the history of breast cancer diagnosed 10 years ago. The umor was positive for estrogen receptors on pathology.\nWhich one of the following would be the most appropriate management?","options":{"A":"Cyclical estrogen and progesterone.","B":"Progesterone-only HRT.","C":"Paroxetine.","D":"Black cohoch.","E":"Mefenamic acid."},"source_answer":"C","source_explanation":"Hot flush is a sudden feeling of warmth that is generally most intense over the face, neck, and chest. The duration is variable but on average lasts about 3-4 minutes. It is often accompanied by sweating that can be profuse and followed by a chill.\nHot flushes are seen in perimenopausal women as one of the most common complaints, and is the only indication to start hormone replacement therapy (HRT). HRT is the most effective treatment for severe hot flushes and is a reasonable choice in\nthe absence of contraindications.\n(Options A and B) Hormonal therapy including estrogen and progesterone is avoided in patients with history of breast cancer, although the effect of progesterone on breast cancer is not established.\nWomen with hot flushes and contraindications to hormonal therapy may benefit from selective serotonin reuptake inhibitor (first-line) such as paroxetine, or other medications such as gabapentin or velnafaxine.\nSSRI are widely used in Australia for management of hot flushes when there is contraindication to hormone therapy. It also improves mood symptoms. Paroxetine is the most common prescribed SSRI (and the only one approved by FDA in US). SSRIs\nare not as effective as HRT, but definitely more effective than placebo. It is important to note that paroxetine, fluoxetine, duloxetine, and bupropion should not be used in patients who are currently on tamoxifen because it interferes with the\nconversion of tamoxifen to its active metabolite endoxifen.\n(Option D) Black Cohosh acts by unknown mechanism and is used for hot flushes. Many studies have found no significant benefit over placebo.\n(Option E) Mefenamic acid may help for short-term control of menopausal symptoms; however, its long term use is controversial and not recommended.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","duration","management","therapy","treatment"],"likely_visual_question":false,"parser_confidence":"high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"68d161de2fcf987496b4dbbe861c489b078de229","duplicate_group_id":"exact-68d161de2fcf","duplicate_sources":[{"record_id":"51ef97fab6487a55d958","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":930,"source_qid":null}]}',1