INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('b5bc9d736493313465f2','Amedex 2023.pdf','936','Mixed/Unclassified','A 26-year-old woman presents to your clinic on the 6th day of her menstrual cycle with mild lower abdominal pain. She lives with her male partner and has no children. On
examination, she has a blood pressure of 110/70 mmHg, pulse rate of 90bpm, and temperature of 37.5°C. No adnexal mass is palpated; however, on vaginal exam cervical motion
tenderness is noted. Which one of the following would be the next best step in management?','{"A":"Transvaginal ultrasonography.","B":"Cervical swabs for culture.","C":"Urine analysis and culture.","D":"Thyroid stimulating hormone.","E":"Abdominal CT scan."}','B','Cervical motion tenderness (also called cervical excitation or chandelier sign) suggests a pelvic pathology. Classically, it is present in pelvic inflammatory disease (PID) and ectopic
pregnancy (EP). Sometimes the test is used to differentiate PID from appendicitis.
This patient is menstruating and less likely to have an EP; therefore, PID re,mains the most likely diagnosis. EP is less likely.
Because of the relatively poor specificity and sensitivity of clinical findings in PID, the Center for Disease Control and (CDC) has established minimal criteria for diagnosis of PID.
In a female patient PID is the diagnosis if:
She is at risk for sexually transmitted disease (STD) AND
She has lower abdominal or pelvic pain without no other identifiable cause for her illness other than PID, AND
on pelvic examination there is (1) cervical motion tenderness or (2) uterine tenderness or (3) adnexal tenderness
In such patients, based on diagnosis of PID, empiric antibiotics should be started after cervical swabs are taken for culture and DNA probe.
Since EP is an important differential diagnosis in a patient with cervical motion tenderness, EP should be excluded. This is correct that in the presence of normal menstruation EP is
very unlikely, but excluding pregnancy would be a good choice if it was among the options.
Ultrasonography is the next best step in management if ectopic pregnancy is suspected based on history, clinical findings and a positive pregnancy test.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"665","duplicate_group_id":"exact-5ee603961bba","duplicate_sources":[{"record_id":"b5bc9d736493313465f2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":936,"source_qid":"665"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"b5bc9d736493313465f2","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":936,"source_qid":"665","domain_hint":"Mixed/Unclassified","stem":"A 26-year-old woman presents to your clinic on the 6th day of her menstrual cycle with mild lower abdominal pain. She lives with her male partner and has no children. On\nexamination, she has a blood pressure of 110/70 mmHg, pulse rate of 90bpm, and temperature of 37.5°C. No adnexal mass is palpated; however, on vaginal exam cervical motion\ntenderness is noted. Which one of the following would be the next best step in management?","options":{"A":"Transvaginal ultrasonography.","B":"Cervical swabs for culture.","C":"Urine analysis and culture.","D":"Thyroid stimulating hormone.","E":"Abdominal CT scan."},"source_answer":"B","source_explanation":"Cervical motion tenderness (also called cervical excitation or chandelier sign) suggests a pelvic pathology. Classically, it is present in pelvic inflammatory disease (PID) and ectopic\npregnancy (EP). Sometimes the test is used to differentiate PID from appendicitis.\nThis patient is menstruating and less likely to have an EP; therefore, PID re,mains the most likely diagnosis. EP is less likely.\nBecause of the relatively poor specificity and sensitivity of clinical findings in PID, the Center for Disease Control and (CDC) has established minimal criteria for diagnosis of PID.\nIn a female patient PID is the diagnosis if:\nShe is at risk for sexually transmitted disease (STD) AND\nShe has lower abdominal or pelvic pain without no other identifiable cause for her illness other than PID, AND\non pelvic examination there is (1) cervical motion tenderness or (2) uterine tenderness or (3) adnexal tenderness\nIn such patients, based on diagnosis of PID, empiric antibiotics should be started after cervical swabs are taken for culture and DNA probe.\nSince EP is an important differential diagnosis in a patient with cervical motion tenderness, EP should be excluded. This is correct that in the presence of normal menstruation EP is\nvery unlikely, but excluding pregnancy would be a good choice if it was among the options.\nUltrasonography is the next best step in management if ectopic pregnancy is suspected based on history, clinical findings and a positive pregnancy test.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","antibiotic","management","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"5ee603961bba0b9ac5face9e02dec7d1f2f08716","duplicate_group_id":"exact-5ee603961bba","duplicate_sources":[{"record_id":"b5bc9d736493313465f2","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":936,"source_qid":"665"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=e