INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('51fbe6d0968dc533ff53','Amedex 2023.pdf','950','Mixed/Unclassified','A 29-year-old woman presents with two episodes of bleeding, one hour apart at 39 weeks gestation. She has no abdominal pain or any other complaints. Physical exam is
inconclusive. An ultrasound scan reveals placenta previa. Which one of the following is the most appropriate next step in management?','{"A":"Admit her for supervision.","B":"Discharge her home.","C":"Induction of labor.","D":"Cesarean section.","E":"Vaginal examination."}','D','Most women who initially present with symptomatic placenta previa respond to supportive therapy, and do not require immediate delivery. Even a large bleed does not preclude
conservative management. Management of placenta previa when mother and fetus are stable is conservative until 38 weeks pregnancy when delivery should be performed by
cesarean section. Since this woman is already at 39 weeks gestation, cesarean section without further need to document fetal lung maturity would be the most appropriate option.
Admission for supervision (option A) was the appropriate option at earlier gestational ages (<37 weeks) where expectant management (if mother and fetus were stable)
was considered until adequate fetal maturity is ensured.
Vaginal delivery is contraindicated in placenta previa most of the time, so induction of labor (option C) is inappropriate. Digital vaginal examination (option E) should be avoided in
patients with placenta previa.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"770","duplicate_group_id":"exact-585e37549fe5","duplicate_sources":[{"record_id":"51fbe6d0968dc533ff53","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":950,"source_qid":"770"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"51fbe6d0968dc533ff53","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":950,"source_qid":"770","domain_hint":"Mixed/Unclassified","stem":"A 29-year-old woman presents with two episodes of bleeding, one hour apart at 39 weeks gestation. She has no abdominal pain or any other complaints. Physical exam is\ninconclusive. An ultrasound scan reveals placenta previa. Which one of the following is the most appropriate next step in management?","options":{"A":"Admit her for supervision.","B":"Discharge her home.","C":"Induction of labor.","D":"Cesarean section.","E":"Vaginal examination."},"source_answer":"D","source_explanation":"Most women who initially present with symptomatic placenta previa respond to supportive therapy, and do not require immediate delivery. Even a large bleed does not preclude\nconservative management. Management of placenta previa when mother and fetus are stable is conservative until 38 weeks pregnancy when delivery should be performed by\ncesarean section. Since this woman is already at 39 weeks gestation, cesarean section without further need to document fetal lung maturity would be the most appropriate option.\nAdmission for supervision (option A) was the appropriate option at earlier gestational ages (<37 weeks) where expectant management (if mother and fetus were stable)\nwas considered until adequate fetal maturity is ensured.\nVaginal delivery is contraindicated in placenta previa most of the time, so induction of labor (option C) is inappropriate. Digital vaginal examination (option E) should be avoided in\npatients with placenta previa.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","management","pregnan","therapy"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"585e37549fe5f0b79168ff818d9438a5cfad4c64","duplicate_group_id":"exact-585e37549fe5","duplicate_sources":[{"record_id":"51fbe6d0968dc533ff53","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":950,"source_qid":"770"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
