INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('51fbe6d0968dc533ff53','src-v294-687f312c','770','950','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','A 29-year-old woman presents with two episodes of bleeding, one hour apart at 39 weeks gestation. She has no abdominal pain or any other complaints. Physical exam is
inconclusive. An ultrasound scan reveals placenta previa. Which one of the following is the most appropriate next step in management?',NULL,'D','Most women who initially present with symptomatic placenta previa respond to supportive therapy, and do not require immediate delivery. Even a large bleed does not preclude
conservative management. Management of placenta previa when mother and fetus are stable is conservative until 38 weeks pregnancy when delivery should be performed by
cesarean section. Since this woman is already at 39 weeks gestation, cesarean section without further need to document fetal lung maturity would be the most appropriate option.
Admission for supervision (option A) was the appropriate option at earlier gestational ages (<37 weeks) where expectant management (if mother and fetus were stable)
was considered until adequate fetal maturity is ensured.
Vaginal delivery is contraindicated in placenta previa most of the time, so induction of labor (option C) is inappropriate. Digital vaginal examination (option E) should be avoided in
patients with placenta previa.',NULL,'Retain the source-era answer for question-bank study; verify current Australian guidance before clinical use.',NULL,NULL,'2023','v2.9.4',1,'text','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"770","duplicate_group_id":"exact-585e37549fe5","duplicate_sources":[{"record_id":"51fbe6d0968dc533ff53","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":950,"source_qid":"770"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,'needs_verification','[]','high') ON CONFLICT(id) DO UPDATE SET source_id=excluded.source_id,source_question_no=excluded.source_question_no,source_page=excluded.source_page,domain=excluded.domain,system=excluded.system,topic=excluded.topic,clinical_task=excluded.clinical_task,stem_en=excluded.stem_en,answer_key=excluded.answer_key,source_explanation_en=excluded.source_explanation_en,memory_rule_en=excluded.memory_rule_en,image_ref=excluded.image_ref,source_year=excluded.source_year,import_version=excluded.import_version,active=1,options_mode=excluded.options_mode,provenance_json=excluded.provenance_json,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk;
