INSERT INTO canonical_records (record_id,source_file,source_page,domain,stem,options_json,source_answer,source_explanation,provenance_json,visual_asset,visual_url,options_mode,current_answer,current_answer_status,current_evidence_json,currentness_risk,record_json,active_quiz,import_version,imported_at) VALUES ('d17c87d0f5af44888d73','Amedex 2023.pdf','960','Mixed/Unclassified','Which one of the following drugs has the highest rate of congenital malformations if used in pregnancy?','{"A":"Carbamazepine.","B":"Phenytoin.","C":"Sodium valproate.","D":"Levetiracetam.","E":"Lamotrigine."}','C','Sodium valproate carries the highest teratogenicity rate among all antiepileptic drugs. The potential congenital defects caused by sodium valproate are shown in the following table:
Neural tube defects
Spina bifida, anencephaly
Heart defects
Congenital ventricular septal defect, aortic stenosis, patent ductus arteriosus, aberrant pulmonary artery
Limb defects
Radial ray defect, polydactyly (more than 5 fingers), oligodactyly (less than 5 fingers), absent fingers,
overlapping toes, camptodactyly (fixed flexion deformity of one or more proximal interphalangeal joints), split
hand, ulnar or tibial hypoplasia, 
Genitourinary defects
Hypospadias, renal hypoplasia, hydronephrosis, duplication of calyceal system
Brain anomalies
Hydranencephal (1), porencephaly(2), arachnoid cysts, cerebral atrophy, partial agenesis of corpus callosum,
agenesis of septum pellucidum, lissencephaly (3) of medial sides of occipital lobes, Dandy-Walker anomaly
(4)
Eye anomalies
Bilateral congenital cataract, optic nerve hypoplasia, tear duct anomalies, microphthalmia, bilateral iris
defects, corneal opacities
Respiratory tract defects
Tracheomalacia , lung hypoplasia, severe laryngeal hypoplasia, abnormal lobulation of the right lung, right
oligemic (less blood flow) lung
Abdominal wall defects
Omphalocele
Skin abnormalities
Capillary hemangioma, aplasia cutis congenital of the scalp
 
All other medications mentioned carry the risk of congenital malformations at a lower rate compared to valproic acid.
 
(1) Also called hydrancephaly is absence of cerebral hemispheres and replacement of the vacant parts of the cranium with cerebrospinal fluid.
(2) A congenital disorder characterised by presence of cysts or cavities within the cerebral hemisphere.
(3) Literally meaning ‘smooth brain’ is caused by defective central nervous migration during the 12th and 24th weeks of gestation resulting in lack of development of the brain folds (gyri) and grooves(sulci)
(4) Dandy – Walker syndrome is a congenital malformation of the cerebellum with the key feature being complete absence of the cerebellar vermis.','{"source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","supporting_pages":[],"source_qid":"131","duplicate_group_id":"exact-aef78c2233e2","duplicate_sources":[{"record_id":"d17c87d0f5af44888d73","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":960,"source_qid":"131"}],"parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","parser_mode":"strict_ocr_tolerant","text_method":"native","visual_asset":null,"asset_preview_url":null}',NULL,NULL,NULL,NULL,'needs_verification','[]','high','{"record_id":"d17c87d0f5af44888d73","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_year":2023,"source_page":960,"source_qid":"131","domain_hint":"Mixed/Unclassified","stem":"Which one of the following drugs has the highest rate of congenital malformations if used in pregnancy?","options":{"A":"Carbamazepine.","B":"Phenytoin.","C":"Sodium valproate.","D":"Levetiracetam.","E":"Lamotrigine."},"source_answer":"C","source_explanation":"Sodium valproate carries the highest teratogenicity rate among all antiepileptic drugs. The potential congenital defects caused by sodium valproate are shown in the following table:\nNeural tube defects\nSpina bifida, anencephaly\nHeart defects\nCongenital ventricular septal defect, aortic stenosis, patent ductus arteriosus, aberrant pulmonary artery\nLimb defects\nRadial ray defect, polydactyly (more than 5 fingers), oligodactyly (less than 5 fingers), absent fingers,\noverlapping toes, camptodactyly (fixed flexion deformity of one or more proximal interphalangeal joints), split\nhand, ulnar or tibial hypoplasia, \nGenitourinary defects\nHypospadias, renal hypoplasia, hydronephrosis, duplication of calyceal system\nBrain anomalies\nHydranencephal (1), porencephaly(2), arachnoid cysts, cerebral atrophy, partial agenesis of corpus callosum,\nagenesis of septum pellucidum, lissencephaly (3) of medial sides of occipital lobes, Dandy-Walker anomaly\n(4)\nEye anomalies\nBilateral congenital cataract, optic nerve hypoplasia, tear duct anomalies, microphthalmia, bilateral iris\ndefects, corneal opacities\nRespiratory tract defects\nTracheomalacia , lung hypoplasia, severe laryngeal hypoplasia, abnormal lobulation of the right lung, right\noligemic (less blood flow) lung\nAbdominal wall defects\nOmphalocele\nSkin abnormalities\nCapillary hemangioma, aplasia cutis congenital of the scalp\n \nAll other medications mentioned carry the risk of congenital malformations at a lower rate compared to valproic acid.\n \n(1) Also called hydrancephaly is absence of cerebral hemispheres and replacement of the vacant parts of the cranium with cerebrospinal fluid.\n(2) A congenital disorder characterised by presence of cysts or cavities within the cerebral hemisphere.\n(3) Literally meaning ‘smooth brain’ is caused by defective central nervous migration during the 12th and 24th weeks of gestation resulting in lack of development of the brain folds (gyri) and grooves(sulci)\n(4) Dandy – Walker syndrome is a congenital malformation of the cerebellum with the key feature being complete absence of the cerebellar vermis.","source_answer_status":"present","current_answer":null,"current_answer_status":"needs_verification","current_evidence":[],"currentness_risk":"high","currentness_keywords":["age","drug","pregnan"],"likely_visual_question":false,"parser_confidence":"very_high","parser_mode":"strict_ocr_tolerant","text_method":"native","parser_version":"2.7.1-parser-only-conservative-staging-2026-09-22","stem_hash":"aef78c2233e237940b098437ce6eb73471dda8f1","duplicate_group_id":"exact-aef78c2233e2","duplicate_sources":[{"record_id":"d17c87d0f5af44888d73","record_type":"text_mcq","source_file":"Amedex 2023.pdf","source_relative_path":"AMEDEX2025+redbook+handbook图片题/Amedex 2023.pdf","source_page":960,"source_qid":"131"}]}',1,'v2.9.4','2026-09-24T00:00:00.000Z') ON CONFLICT(record_id) DO UPDATE SET source_file=excluded.source_file,source_page=excluded.source_page,domain=excluded.domain,stem=excluded.stem,options_json=excluded.options_json,source_answer=excluded.source_answer,source_explanation=excluded.source_explanation,provenance_json=excluded.provenance_json,visual_asset=excluded.visual_asset,visual_url=excluded.visual_url,options_mode=excluded.options_mode,current_answer=excluded.current_answer,current_answer_status=excluded.current_answer_status,current_evidence_json=excluded.current_evidence_json,currentness_risk=excluded.currentness_risk,record_json=excluded.record_json,active_quiz=excluded.active_quiz,import_version=excluded.import_version,imported_at=excluded.imported_at;
