INSERT INTO questions (id,source_id,source_question_no,source_page,domain,system,topic,clinical_task,stem_en,stem_zh,answer_key,source_explanation_en,source_explanation_zh,memory_rule_en,memory_rule_zh,image_ref,source_year,import_version,active,options_mode,provenance_json,current_answer,current_answer_status,current_evidence_json,currentness_risk) VALUES ('d17c87d0f5af44888d73','src-v294-687f312c','131','960','Mixed/Unclassified','Mixed/Unclassified','Mixed/Unclassified','AMC MCQ','Which one of the following drugs has the highest rate of congenital malformations if used in pregnancy?',NULL,'C','Sodium valproate carries the highest teratogenicity rate among all antiepileptic drugs. The potential congenital defects caused by sodium valproate are shown in the following table:
